What are functions?

Reusable blocks of code that performs a specific task and can be called upon whenever needed within a program

function (x, na.rm = FALSE) {
  sqrt(var(if (is.vector(x) || is.factor(x)) x else as.double(x), 
           na.rm = na.rm))
}

Syntax

my_func &lt;- function(&lt;input parameters&gt;) {
    &lt;action&gt;
    return (&lt;return value&gt;)
}

Examples


second_item &lt;- function(my_list) {
    second &lt;- my_list[2]
    return (second)
}

result &lt;- second_item(c(1,5,3,6))
print(result)

[1] 5

Examples


find_ten &lt;- function(my_list) {
    count &lt;- 0
    for (x in my_list) {
        if (x == 10) {
            count &lt;- count + 1
        }
    }
    return (count)
}
result &lt;- find_ten(c(1,4,10,5,10))
print(result)

[1] 2

